    if self.has_any_ignore_rules() {
        let mat = self.matched_ignore(path, is_dir);
        if mat.is_ignore() {
            return mat;
        } else if mat.is_whitelist() {
            whitelisted = mat;
        }
    }
    if !self.0.types.is_empty() {
        let mat =
            self.0.types.matched(path, is_dir).map(IgnoreMatch::types);
        if mat.is_ignore() {
            return mat;
        } else if mat.is_whitelist() {
            whitelisted = mat;
        }
    }
    whitelisted
}

